def check(fn):
    bad=[(i,j,g[i][j],fn(i,j)) for i in range(n) for j in range(m) if g[i][j]!=6 and fn(i,j)!=6 and g[i][j]!=fn(i,j)]
    return len(bad)
print('mirror-h', check(lambda i,j:g[i][m-1-j]))
print('mirror-v', check(lambda i,j:g[n-1-i][j]))
print('transpose', check(lambda i,j:g[j][i]))

import numpy as np
a=np.array(g)
