from collections import deque
seen=set(); comps=[]
for i in range(n):
    for j in range(m):
        if a[i,j]==6 and (i,j) not in seen:
            q=deque([(i,j)]); seen.add((i,j)); c=[]
            while q:
                x,y=q.popleft(); c.append((x,y))
                for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                    p=(x+dx,y+dy)
                    if 0<=p[0]<n and 0<=p[1]<m and a[p]==6 and p not in seen:
                        seen.add(p); q.append(p)
            comps.append(c)
for c in comps:
    ys=[p[0] for p in c]; xs=[p[1] for p in c]
    print(len(c), min(ys),max(ys),min(xs),max(xs))

